    90→
    91→      if (dataExists) {
    92→        await RNFS.unlink(dataPath);
    93→        console.log("Cleared crypto data store");
    94→      }
    95→
    96→      if (cacheExists) {
    97→        await RNFS.unlink(cachePath);
    98→        console.log("Cleared crypto cache store");
    99→      }
   100→    } catch (error) {
