   126→  /** Attempt to restore session from stored credentials */
   127→  public static restoreSession = async (): Promise<boolean> => {
   128→    try {
   129→      const credentials = MatrixStorage.getLoginCredentials();
   130→
   131→      if (!credentials) return false;
   132→
   133→      await this.initialize(credentials.baseUrl);
   134→
   135→      if (!this.instance) throw new Error("Failed to initialize client");
   136→
   137→      // Create client with stored credentials
   138→      await this.instance.restoreSession({
   139→        accessToken: credentials.accessToken,
   140→        refreshToken: credentials.refreshToken,
   141→        userId: credentials.userId,
   142→        deviceId: credentials.deviceId,
   143→        homeserverUrl: credentials.baseUrl,
   144→        oidcData: undefined,
   145→        slidingSyncVersion: SlidingSyncVersion.Native,
   146→      });
   147→
   148→      // Verify the session is valid by making a server request
   149→      try {
   150→        this.profile = await this.instance.getProfile(credentials.userId);
   151→      } catch (error) {
   152→        console.warn("Session validation failed:", error);
   153→        throw new Error("Session is invalid or expired");
   154→      }
   155→
   156→      this.syncService = await this.instance.syncService().finish();
   157→
   158→      if (!this.syncService) {
   159→        throw new Error("Failed to initialize sync service");
   160→      }
   161→
   162→      await this.syncService.start();
   163→
   164→      // Update atoms so providers can react to the initialized service
   165→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   166→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   167→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   168→
   169→      return true;
   170→    } catch (error) {
   171→      console.warn("Failed to restore session:", error);
   172→
   173→      // Clear both credentials and crypto store to ensure clean state
   174→      MatrixStorage.clearLoginCredentials();
   175→      await this.clearCryptoStore();
   176→
   177→      // Reset the instance so it can be recreated fresh
   178→      this.instance = null;
   179→      this.syncService = null;
   180→
   181→      // Clear atoms
   182→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   183→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   184→
   185→      return false;
   186→    }
