   189→  /** Call this after logging in to create a new client instance with the provided account.  */
   190→  public static setup = async (params: Session) => {
   191→    // Clear any existing crypto store to prevent device ID mismatches
   192→    await this.clearCryptoStore();
   193→
   194→    // Stop and clear existing instances
   195→    if (this.syncService) await this.syncService.stop();
   196→    this.instance = null;
   197→    this.syncService = null;
   198→
   199→    // Save credentials for future auto-login
   200→    MatrixStorage.saveLoginCredentials({
   201→      accessToken: params.accessToken,
   202→      refreshToken: params.refreshToken,
   203→      userId: params.userId,
   204→      deviceId: params.deviceId,
   205→      baseUrl: params.homeserverUrl,
   206→    });
   207→
   208→    // Create a fresh client instance and configure it with the session + sliding sync
   209→    await this.initialize(params.homeserverUrl);
   210→
   211→    if (!this.instance) throw new Error("Failed to initialize client");
   212→
   213→    // Use local variable to help TypeScript with type narrowing
   214→    const client: ClientInterface = this.instance;
   215→
   216→    await client.restoreSession({
   217→      accessToken: params.accessToken,
   218→      refreshToken: params.refreshToken,
   219→      userId: params.userId,
   220→      deviceId: params.deviceId,
   221→      homeserverUrl: params.homeserverUrl,
   222→      oidcData: undefined,
   223→      slidingSyncVersion: SlidingSyncVersion.Native,
   224→    });
   225→
   226→    // Verify the session is valid by making a server request
   227→    // Use the params.userId since client.userId() might not be populated yet
   228→    try {
   229→      this.profile = await client.getProfile(params.userId);
   230→    } catch (error) {
   231→      console.warn("Session validation failed:", error);
   232→      throw new Error("Session is invalid or expired");
   233→    }
   234→
   235→    this.syncService = await client.syncService().finish();
   236→
   237→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   238→
   239→    await this.syncService.start();
   240→    await client.encryption().waitForE2eeInitializationTasks();
   241→
   242→    // Check if we need to bootstrap cross-signing or enable backups
   243→    try {
   244→      const encryption = client.encryption();
   245→      const backupExists = await encryption.backupExistsOnServer();
   246→      console.log("Backup exists on server:", backupExists);
   247→      console.log(
   248→        "Current verification state:",
   249→        encryption.verificationState(),
   250→      );
   251→
   252→      // If no backup exists and we're the only device, we might need to set one up
   253→      const isLastDevice = await encryption.isLastDevice();
   254→      console.log("Is last device:", isLastDevice);
   255→
   256→      if (!backupExists) {
   257→        console.log("Enabling backups for cross-signing...");
   258→        await encryption.enableBackups();
   259→      }
   260→
   261→      // Update atoms so providers can react to the initialized service
   262→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   263→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   264→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   265→    } catch (error) {
   266→      console.warn("Failed to check backup/verification status:", error);
   267→    }
   268→  };
