   421→  /** Deactivate the user's account permanently
   422→   * Warning: This is irreversible and will delete all user data */
   423→  public static deactivateAccount = async (password: string) => {
   424→    if (!this.instance) throw new Error("Client not initialized");
   425→
   426→    try {
   427→      // First request with undefined auth_data (will always fail per UIA spec)
   428→      try {
   429→        await this.instance.deactivateAccount(undefined, true);
   430→      } catch {
   431→        // Expected to fail
   432→      }
   433→
   434→      console.log(this.instance.userId(), "userId");
   435→      const userId = this.instance.userId();
   436→      if (!userId) throw new Error("User ID not found");
   437→
   438→      const authData = new AuthData.Password({
   439→        passwordDetails: AuthDataPasswordDetails.create({
   440→          identifier: userId,
   441→          password,
   442→        }),
   443→      });
   444→
   445→      // Step 4: Second request with auth data
   446→      await this.instance.deactivateAccount(authData, true);
   447→
   448→      // After successful deactivation, clean up local data
   449→      await this.logout();
   450→    } catch (error) {
   451→      console.error("Failed to deactivate account:", error);
   452→      throw error;
   453→    }
   454→  };
