     1→import { MemoryStore } from "matrix-js-sdk";
     2→import { MMKV } from "react-native-mmkv";
     3→import { SecureStoreKeys } from "../models";
     4→
     5→const minimalMMKVStorage = new MMKV({
     6→  id: "matrix-js-sdk-minimal-data",
     7→});
     8→
     9→class MMKVMinimalStore extends MemoryStore {
    10→  private mmkv: MMKV;
    11→  private prefix: string;
    12→
    13→  constructor() {
    14→    super();
    15→    this.mmkv = minimalMMKVStorage;
    16→    this.prefix = "mx_minimal_sdk_";
    17→  }
    18→
    19→  startup = async (): Promise<void> => {
    20→    const syncToken: string | undefined = this.mmkv.getString(
    21→      `${this.prefix}syncToken`,
    22→    );
    23→
    24→    if (syncToken) {
    25→      super.setSyncToken(syncToken);
    26→    }
    27→
    28→    return super.startup();
    29→  };
    30→
    31→  deleteAllData = async (): Promise<void> => {
    32→    const keysToDelete: string[] = this.mmkv
    33→      .getAllKeys()
    34→      .filter((key) => key.startsWith(this.prefix));
    35→
    36→    for (const key of keysToDelete) {
    37→      this.mmkv.delete(key);
    38→    }
    39→
    40→    await super.deleteAllData();
    41→  };
    42→
    43→  setSyncToken = (token: string) => {
    44→    this.mmkv.set(`${this.prefix}syncToken`, token);
    45→    super.setSyncToken(token);
    46→  };
    47→
    48→  getSyncToken = (): string | null => {
    49→    const token: string | null =
    50→      this.mmkv.getString(`${this.prefix}syncToken`) || null;
    51→
    52→    return token || super.getSyncToken();
    53→  };
    54→
    55→  // Login credentials storage methods
    56→  saveLoginCredentials = (credentials: {
    57→    accessToken: string;
    58→    refreshToken?: string;
    59→    userId: string;
    60→    deviceId: string;
    61→    baseUrl: string;
    62→  }) => {
    63→    this.mmkv.set(SecureStoreKeys.MATRIX_ACCESS_TOKEN, credentials.accessToken);
    64→    this.mmkv.set(SecureStoreKeys.MATRIX_USER_ID, credentials.userId);
    65→    this.mmkv.set(SecureStoreKeys.MATRIX_DEVICE_ID, credentials.deviceId);
    66→    this.mmkv.set(SecureStoreKeys.MATRIX_BASE_URL, credentials.baseUrl);
    67→
    68→    if (credentials.refreshToken) {
    69→      this.mmkv.set(
    70→        SecureStoreKeys.MATRIX_REFRESH_TOKEN,
    71→        credentials.refreshToken,
    72→      );
    73→    }
    74→  };
    75→
    76→  getLoginCredentials = () => {
    77→    const accessToken = this.mmkv.getString(
    78→      SecureStoreKeys.MATRIX_ACCESS_TOKEN,
    79→    );
    80→    const userId = this.mmkv.getString(SecureStoreKeys.MATRIX_USER_ID);
    81→    const deviceId = this.mmkv.getString(SecureStoreKeys.MATRIX_DEVICE_ID);
    82→    const baseUrl = this.mmkv.getString(SecureStoreKeys.MATRIX_BASE_URL);
    83→    const refreshToken = this.mmkv.getString(
    84→      SecureStoreKeys.MATRIX_REFRESH_TOKEN,
    85→    );
    86→
    87→    if (!accessToken || !userId || !deviceId || !baseUrl) {
    88→      return null;
    89→    }
    90→
    91→    return {
    92→      accessToken,
    93→      userId,
    94→      deviceId,
    95→      baseUrl,
    96→      ...(refreshToken && { refreshToken }),
    97→    };
    98→  };
    99→
   100→  clearLoginCredentials = () => {
   101→    this.mmkv.delete(SecureStoreKeys.MATRIX_ACCESS_TOKEN);
   102→    this.mmkv.delete(SecureStoreKeys.MATRIX_REFRESH_TOKEN);
   103→    this.mmkv.delete(SecureStoreKeys.MATRIX_USER_ID);
   104→    this.mmkv.delete(SecureStoreKeys.MATRIX_DEVICE_ID);
   105→    this.mmkv.delete(SecureStoreKeys.MATRIX_BASE_URL);
   106→    this.mmkv.delete(`${this.prefix}syncToken`);
   107→  };
   108→
   109→  hasStoredCredentials = () => !!this.getLoginCredentials();
   110→
   111→  // All other methods will fall back to MemoryStore's in-memory implementation.
   112→  // They won't persist across app restarts unless explicitly overridden.
   113→}
   114→
   115→export const MatrixStorage = new MMKVMinimalStore();
