     8→export const VerificationProvider: FC = () => {
     9→  const client = useAtomValue(MatrixAtoms.matrixClient);
    10→  const syncService = useAtomValue(MatrixAtoms.syncService);
    11→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    12→  const setVerificationEmojis = useSetAtom(MatrixAtoms.verificationEmojis);
    13→  const setVerificationSenderName = useSetAtom(
    14→    MatrixAtoms.verificationSenderName,
