    37→          (emojis) => {
    38→            setVerificationEmojis(emojis);
    39→            setVerificationStatus("emojis");
    40→          },
    41→          // On state change
    42→          (state) => {
    43→            console.log("Verification state changed:", state);
    44→
    45→            if (state === "success") {
