    55→              setVerificationEmojis(null);
    56→              setVerificationSenderName(null);
    57→              Toast.show({
    58→                type: "error",
    59→                text1: "Verification failed",
    60→              });
    61→            } else if (state === "cancelled") {
    62→              setVerificationStatus("cancelled");
    63→              setVerificationEmojis(null);
    64→              setVerificationSenderName(null);
    65→              Toast.show({
    66→                type: "error",
    67→                text1: "Verification cancelled",
    68→              });
    69→            } else if (state === "emojis") {
    70→              setVerificationStatus("emojis");
    71→            } else if (state === "accepted") {
    72→              setVerificationStatus("accepted");
    73→            } else if (state === "sasStarted") {
    74→              setVerificationStatus("sasStarted");
    75→            }
    76→          },
    77→        );
    78→        return unsubscribe;
