     1→import type { MediaSourceInterface } from "@unomed/react-native-matrix-sdk";
     2→import { MatrixService } from "../services";
     3→import { getHttpUriForMxc } from "./getHttpUriForMxc";
     4→
     5→interface PropsWithUrl {
     6→  url: string;
     7→  serverUrl: string;
     8→  width?: number;
     9→  height?: number;
    10→  resizeMode?: "scale" | "crop";
    11→}
    12→
    13→interface PropsWithMediaSource {
    14→  serverUrl: string;
    15→  mediaSource: MediaSourceInterface;
    16→  mimeType?: string;
    17→}
    18→
    19→type Props = PropsWithUrl | PropsWithMediaSource;
    20→
    21→/**
    22→ * Fetches image from Matrix
    23→ * For MediaSource: Handles both encrypted and unencrypted images automatically
    24→ * For plain URL: Fetches from MXC URL (for avatars, etc.)
    25→ */
    26→export const fetchMedia = async (props: Props) => {
    27→  if (!MatrixService.instance) {
    28→    throw new Error("Matrix client not initialized");
    29→  }
    30→
    31→  try {
    32→    // Handle MediaSource (for message images - supports encryption)
    33→    if ("mediaSource" in props) {
    34→      const { mediaSource, mimeType = "image/jpeg" } = props;
    35→
    36→      // Use SDK's getMediaFile which handles decryption automatically
    37→      const mediaHandle = await MatrixService.instance.getMediaFile(
    38→        mediaSource,
    39→        undefined, // filename
    40→        mimeType,
    41→        true, // useCache
    42→        undefined, // tempDir - uses system default
    43→      );
    44→
    45→      const filePath = mediaHandle.path();
    46→      return filePath.startsWith("file://") ? filePath : `file://${filePath}`;
    47→    }
    48→
    49→    // Handle plain URL (for avatars, room images - typically unencrypted)
    50→    const {
    51→      url,
    52→      width = 32,
    53→      height = 32,
    54→      resizeMode = "scale",
    55→      serverUrl,
    56→    } = props;
    57→
    58→    const uri = getHttpUriForMxc(
    59→      serverUrl,
    60→      url,
    61→      width,
    62→      height,
    63→      resizeMode,
    64→      true,
    65→      true,
    66→      true,
    67→    );
    68→
    69→    if (!uri) return null;
    70→
    71→    const res = await fetch(uri, {
    72→      headers: {
    73→        Authorization: `Bearer ${MatrixService.instance.session().accessToken}`,
    74→      },
    75→    });
    76→
    77→    return res.url;
    78→  } catch (error) {
    79→    console.error("Failed to fetch image:", error);
    80→    return null;
    81→  }
    82→};
