    52→export const useRoomTimeline = ({ room, roomId }: Props) => {
    53→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    54→  const [loadingMessage, setLoadingMessage] = useState(true);
    55→  /** Track processed verification request IDs to avoid duplicates */
    56→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
    57→  const [refreshing, setRefreshing] = useState(false);
    58→  const [updateTrigger, setUpdateTrigger] = useState(0);
    59→  const eventIdsRef = useRef<Set<string>>(new Set());
    60→  const timelineRef = useRef<TimelineInterface | null>(null);
    61→  const isPaginatingRef = useRef(false);
    62→  const timelinePaginateNumber = useRef<number>(20);
    63→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    64→
    65→  const upsertEvents = (incoming: EventTimelineItem[]) => {
    66→    setEvents((prev) => {
    67→      const next = [...prev];
    68→      for (const e of incoming) {
    69→        const id = getEventId(e);
    70→        if (!id) continue;
    71→        if (!eventIdsRef.current.has(id)) {
    72→          eventIdsRef.current.add(id);
    73→          next.push(e);
    74→        }
    75→      }
    76→      return next;
    77→    });
    78→  };
    79→
    80→  const handleVerificationRequest = (info: {
    81→    senderId: string;
    82→    flowId: string;
    83→  }) => {
    84→    setVerificationStatus("incomingRequest");
    85→    NavigationContainerRef.navigate("verifyUser", {
    86→      userId: info.senderId,
    87→      flowId: info.flowId,
