   158→    let timelineListenerHandle: TaskHandleInterface | null = null;
   159→
   160→    const initRoomTimeline = async () => {
   161→      try {
   162→        const timeline = await room.timelineWithConfiguration({
   163→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
   164→          filter: new TimelineFilter.All(),
   165→          internalIdPrefix: undefined,
   166→          dateDividerMode: DateDividerMode.Daily,
   167→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
   168→          reportUtds: false,
   169→        });
   170→
   171→        // Store timeline in ref for reuse in pagination
   172→        timelineRef.current = timeline;
   173→
   174→        await timeline.paginateBackwards(timelinePaginateNumber.current);
   175→        timelinePaginateNumber.current += 20;
   176→        setLoadingMessage(false);
   177→
   178→        // Set up timeline listener for real-time updates
   179→        timelineListenerHandle = await timeline.addListener({
   180→          onUpdate: (diffs) => {
   181→            markAsRead();
   182→            // Trigger re-render to update read receipts and other event properties
   183→            setUpdateTrigger((prev) => prev + 1);
   184→            diffs.forEach((diff) => {
   185→              const change = diff.tag;
   186→              switch (change) {
   187→                case TimelineDiff_Tags.Append: {
   188→                  const newItems = diff.inner.values;
   189→                  if (newItems.length) {
   190→                    const eventItems = newItems
   191→                      .map((i) => i.asEvent())
   192→                      .filter((i): i is EventTimelineItem => !!i);
   193→
   194→                    if (eventItems.length > 0) {
   195→                      upsertEvents(eventItems);
   196→                      checkForVerificationRequests(eventItems);
   197→                    }
   198→                  }
   199→                  break;
   200→                }
   201→                case TimelineDiff_Tags.Insert: {
   202→                  const { value } = diff.inner;
   203→                  const ev = value.asEvent();
   204→                  if (ev) {
   205→                    upsertEvents([ev]);
   206→                    checkForVerificationRequests([ev]);
   207→                  }
   208→                  break;
   209→                }
   210→                case TimelineDiff_Tags.Set: {
   211→                  const { index, value } = diff.inner;
   212→                  const ev = value.asEvent();
   213→                  if (ev) {
   214→                    const id = getEventId(ev);
   215→                    if (!id) break;
   216→
   217→                    setEvents((prev) => {
   218→                      const next = [...prev];
   219→                      // Guard against out-of-range (indexes may include non-event items upstream)
   220→                      if (index >= 0 && index < next.length) {
   221→                        // Check if we're updating the same event or creating a duplicate
   222→                        const existingId = getEventId(next[index]);
   223→                        if (existingId === id || !eventIdsRef.current.has(id)) {
   224→                          next[index] = ev;
   225→                        }
   226→                      } else {
   227→                        // If index doesn't line up, check for duplicates before adding
   228→                        if (!eventIdsRef.current.has(id)) {
   229→                          next.push(ev);
   230→                        }
   231→                      }
   232→                      // Rebuild Set from next
   233→                      eventIdsRef.current = new Set(
   234→                        next.map(getEventId).filter(Boolean) as string[],
   235→                      );
   236→                      return next;
   237→                    });
   238→                  }
   239→                  break;
   240→                }
   241→                case TimelineDiff_Tags.Remove: {
   242→                  const { index: removeIndex } = diff.inner;
   243→                  setEvents((prev) => {
   244→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   245→                    eventIdsRef.current = new Set(
   246→                      next.map(getEventId).filter(Boolean) as string[],
   247→                    );
   248→                    return next;
   249→                  });
   250→                  break;
   251→                }
   252→                case TimelineDiff_Tags.PushFront: {
   253→                  const { value } = diff.inner;
   254→                  const ev = value.asEvent();
   255→                  if (ev) {
   256→                    const id = getEventId(ev);
   257→                    if (!id) break;
   258→
   259→                    setEvents((prev) => {
   260→                      // Check for duplicate inside setState to prevent race conditions
   261→                      if (eventIdsRef.current.has(id)) return prev;
   262→                      eventIdsRef.current.add(id);
   263→                      return [ev, ...prev];
   264→                    });
   265→                    checkForVerificationRequests([ev]);
   266→                  }
   267→                  break;
   268→                }
   269→                case TimelineDiff_Tags.PushBack: {
   270→                  const { value } = diff.inner;
   271→                  const ev = value.asEvent();
   272→                  if (ev) {
   273→                    const id = getEventId(ev);
   274→                    if (!id) break;
   275→
   276→                    setEvents((prev) => {
   277→                      // Check for duplicate inside setState to prevent race conditions
   278→                      if (eventIdsRef.current.has(id)) return prev;
   279→                      eventIdsRef.current.add(id);
   280→                      return [...prev, ev];
   281→                    });
   282→                    checkForVerificationRequests([ev]);
   283→                  }
   284→                  break;
   285→                }
   286→                case TimelineDiff_Tags.Reset: {
   287→                  const resetItems = diff.inner.values;
   288→                  if (resetItems.length) {
   289→                    const eventItems = resetItems
   290→                      .map((i) => i.asEvent())
   291→                      .filter((i): i is EventTimelineItem => !!i);
   292→
   293→                    // Deduplicate events in case Reset contains duplicates
   294→                    const seenIds = new Set<string>();
   295→                    const uniqueEvents: EventTimelineItem[] = [];
   296→
   297→                    for (const event of eventItems) {
   298→                      const id = getEventId(event);
   299→                      if (id && !seenIds.has(id)) {
   300→                        seenIds.add(id);
   301→                        uniqueEvents.push(event);
   302→                      }
   303→                    }
   304→
   305→                    eventIdsRef.current = seenIds;
   306→                    setEvents(uniqueEvents);
   307→                  }
   308→                  break;
   309→                }
   310→                case TimelineDiff_Tags.Truncate: {
   311→                  const { length: cut } = diff.inner;
   312→                  setEvents((prev) => {
   313→                    const next = prev.slice(0, cut);
   314→                    eventIdsRef.current = new Set(
   315→                      next.map(getEventId).filter(Boolean) as string[],
   316→                    );
   317→                    return next;
   318→                  });
   319→                  break;
   320→                }
   321→                default:
   322→                  console.log("Unknown timeline change type:", change);
   323→              }
   324→            });
   325→          },
   326→        });
   327→      } catch (error) {
   328→        console.error("Failed to initialize room timeline:", error);
   329→        return null;
   330→      }
   331→    };
   332→
   333→    initRoomTimeline();
   334→
   335→    return () => {
   336→      timelineListenerHandle?.cancel?.();
   337→      timelineRef.current = null;
   338→    };
   339→  }, [roomId, checkForVerificationRequests]);
   340→
   341→  useEffect(() => {
   342→    markAsRead().catch(console.error);
   343→  }, []);
   344→
   345→  return {
   346→    events,
   347→    loadingMessage,
   348→    refreshing,
   349→    timelineRef,
   350→    isPaginatingRef,
   351→    updateTrigger,
   352→    loadMoreMessages,
   353→    markAsRead,
   354→  };
   355→};
