     1→import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
     2→import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
     3→import { useEffect, useMemo, useState } from "react";
     4→
     5→interface UseRoomInitializationProps {
     6→  room: RoomInterface | undefined;
     7→}
     8→
     9→export const useRoomInitialization = ({ room }: UseRoomInitializationProps) => {
    10→  const [isEncrypted, setIsEncrypted] = useState(false);
    11→  const [roomMembers, setRoomMembers] = useState(0);
    12→  const hasNoCallOption = useMemo(() => {
    13→    return (room?.isPublic() && !isEncrypted) || !isEncrypted;
    14→  }, [room, isEncrypted]);
    15→
    16→  useEffect(() => {
    17→    if (!room) return;
    18→
    19→    room.isEncrypted().then(setIsEncrypted).catch(console.error);
    20→    room
    21→      .members()
    22→      .then((info) => {
    23→        const members = info.nextChunk(100000) ?? [];
    24→        const acceptedMembers = members.filter(
    25→          (member) => member.membership?.tag === MembershipState_Tags.Join,
    26→        );
    27→        setRoomMembers(acceptedMembers.length);
    28→      })
    29→      .catch(console.error);
    30→  }, [room]);
    31→
    32→  return {
    33→    isEncrypted,
    34→    roomMembers,
    35→    hasNoCallOption,
    36→  };
    37→};
