    14→export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
    15→  navigation,
    16→}) => {
    17→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
    18→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
    19→  const hasSeenNotificationsIntro = useAtomValue(
    20→    PushNotificationsAtoms.hasSeenNotificationsIntro,
    21→  );
    22→  const transition = useRef(
    23→    animateParallel(
    24→      { opacity: [0, 1], translateY: [40, 0] },
    25→      { duration: 200 },
    26→    ),
    27→  ).current;
    28→
    29→  useEffect(() => {
    30→    const checkAuthAndNavigate = async () => {
    31→      try {
    32→        // Check if we have stored credentials
    33→        if (MatrixService.hasStoredCredentials()) {
    34→          const sessionRestored = await MatrixService.restoreSession();
    35→          const backupState = await MatrixService.getBackupState();
    36→          const recoveryState = await MatrixService.getRecoveryState();
    37→          const backupExists = backupState === "enabled";
    38→          const recoveryDisabled = recoveryState === RecoveryState.Disabled;
    39→          const isVerified = MatrixService.isDeviceVerified();
    40→          /** If the session is restored and the device is not verified, there is a backup and recovery is not disabled, navigate to the confirm identity screen */
    41→          const needsConfirmIdentity =
    42→            !isVerified && backupExists && !recoveryDisabled;
    43→
    44→          if (sessionRestored && needsConfirmIdentity) {
    45→            navigation.replace("confirmIdentity");
    46→            return;
    47→          }
    48→
    49→          if (!hasSeenOnboarding) {
    50→            navigation.replace("onboarding");
    51→            return;
    52→          }
    53→
    54→          if (!hasSeenNotificationsIntro) {
    55→            navigation.replace("notificationsIntro");
    56→            return;
    57→          }
    58→
    59→          //If there is a screen lock pin, navigate to the verify pin screen
    60→          if (screenLockPin && sessionRestored) {
    61→            navigation.replace("verifyPin", { isSettingsScreen: false });
    62→            return;
    63→          }
    64→
    65→          if (sessionRestored) {
    66→            navigation.replace("home");
    67→            return;
    68→          }
    69→        }
    70→
    71→        await MatrixService.initialize(MatrixBaseURL);
    72→        navigation.replace("welcome");
    73→      } catch (error) {
    74→        console.warn("Error during auth check:", error);
    75→        navigation.replace("welcome");
    76→      }
    77→    };
    78→
    79→    transition.start(() => {
    80→      setTimeout(checkAuthAndNavigate, 2000);
    81→    });
    82→  }, [navigation, hasSeenOnboarding, screenLockPin, transition]);
    83→
    84→  return (
    85→    <ScreenLayout>
    86→      <Block
    87→        animations={transition.animations}
    88→        flex={1}
    89→        align="center"
    90→        justify="space-between"
    91→      >
    92→        <Image
    93→          source={require("assets/images/logo.png")}
    94→          width={88}
    95→          height={66}
    96→          style={styles.logo}
    97→        />
    98→        <Text font="Silkscreen-Regular" size={TextSize.medium}>
    99→          CLOAK
   100→        </Text>

