     1→import {
     2→  type EventTimelineItem,
     3→  MessageType_Tags,
     4→  MsgLikeKind_Tags,
     5→  TimelineItemContent_Tags,
     6→} from "@unomed/react-native-matrix-sdk";
     7→
     8→export const getLastMessageType = (
     9→  event: EventTimelineItem | undefined,
    10→): string => {
    11→  const type = event?.content.tag;
    12→  const senderName = event?.isOwn
    13→    ? "You"
    14→    : event?.senderProfile?.tag === "Ready"
    15→      ? event?.senderProfile?.inner?.displayName || "Unknown"
    16→      : "Unknown";
    17→
    18→  if (
    19→    type === TimelineItemContent_Tags.CallInvite ||
    20→    type === TimelineItemContent_Tags.RtcNotification
    21→  ) {
    22→    return `${senderName}: 🔔 Call notify`;
    23→  }
    24→
    25→  if (type === TimelineItemContent_Tags.MsgLike) {
    26→    const kind = event?.content.inner.content.kind;
    27→    let messageBody = "";
    28→
    29→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    30→      const msgType = kind.inner.content.msgType;
    31→
    32→      if (msgType?.tag === MessageType_Tags.Text) {
    33→        messageBody = kind.inner.content.body || "";
    34→      } else if (msgType?.tag === MessageType_Tags.Image) {
    35→        messageBody = "📷 Image";
    36→      } else if (msgType?.tag === MessageType_Tags.File) {
    37→        messageBody = "📎 File";
    38→      } else if (msgType?.tag === MessageType_Tags.Video) {
    39→        messageBody = "🎥 Video";
    40→      } else if (msgType?.tag === MessageType_Tags.Audio) {
    41→        messageBody = "🎵 Audio";
    42→      } else {
    43→        messageBody = "Message";
    44→      }
    45→    }
    46→
    47→    return `${senderName}: ${messageBody}`;
    48→  }
    49→
    50→  if (type === TimelineItemContent_Tags.RoomMembership) {
    51→    return `${senderName}: Room name changed`;
    52→  }
    53→
    54→  if (type === TimelineItemContent_Tags.ProfileChange) {
    55→    return `${senderName}: Personal settings changed`;
    56→  }
    57→
    58→  return "Unknown message type";
    59→};
