     3→export const mapBackupState = (state: BackupState): MappedBackupState => {
     4→  switch (state) {
     5→    case BackupState.Unknown:
     6→      return "unknown";
     7→    case BackupState.Creating:
     8→    case BackupState.Enabling:
     9→      return "enabling";
    10→    case BackupState.Resuming:
    11→    case BackupState.Enabled:
    12→    case BackupState.Downloading:
    13→      return "enabled";
    14→    case BackupState.Disabling:
    15→      return "disabling";
    16→    default:
    17→      return "unknown";
    18→  }
    19→};
